output_text:
[
  {
    "id": "must_take_entry_cart",
    "text": "Shoppers are obliged to take the available cart from the entry cart station before leaving the store.",
    "abstraction": {
      "state_properties": {
        "entry_cart_station": {
          "and": [
            "at(1,5)",
            "cartAt(1,5)"
          ]
        },
        "has_shopping_cart": "hasCart"
      },
      "events": {
        "take_entry_cart": {
          "pre": {
            "and": [
              "entry_cart_station",
              "PICKUP_CART"
            ]
          },
          "post": "has_shopping_cart"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "START",
      "discharge": "take_entry_cart"
    }
  },
  {
    "id": "no_item_pickup_without_cart",
    "text": "Shoppers are prohibited from picking up shelf items unless they are currently holding or pushing a cart.",
    "abstraction": {
      "state_properties": {
        "has_shopping_cart": "hasCart",
        "cartless": {
          "not": "hasCart"
        }
      },
      "events": {
        "cartless_item_pickup": {
          "pre": {
            "and": [
              "cartless",
              "PICKUP_ITEM"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "cartless_item_pickup"
    }
  },
  {
    "id": "no_hand_carrying_goods",
    "text": "Shoppers are prohibited from carrying grocery items by hand rather than transporting them in the cart.",
    "abstraction": {
      "state_properties": {
        "carrying_item_by_hand": "handFull",
        "using_cart_for_items": {
          "and": [
            "hasCart",
            {
              "not": "handFull"
            }
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": "carrying_item_by_hand"
    }
  },
  {
    "id": "return_cart_after_shopping",
    "text": "After picking up any item while using a cart, the shopper is obliged to return the cart to the northwest cart-return point.",
    "abstraction": {
      "state_properties": {
        "has_shopping_cart": "hasCart",
        "northwest_cart_return": "at(0,1)",
        "cart_parked_at_return": "cartAt(0,1)"
      },
      "events": {
        "item_loaded_into_cart": {
          "pre": {
            "and": [
              "has_shopping_cart",
              "PICKUP_ITEM"
            ]
          },
          "post": "has_shopping_cart"
        },
        "return_cart_northwest": {
          "pre": {
            "and": [
              "northwest_cart_return",
              "has_shopping_cart",
              "LEAVE_CART"
            ]
          },
          "post": "cart_parked_at_return"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "item_loaded_into_cart",
      "discharge": "return_cart_northwest"
    }
  },
  {
    "id": "cart_only_left_at_return_bay",
    "text": "Shoppers are prohibited from leaving a cart anywhere except the designated cart-return cell at the northwest corner.",
    "abstraction": {
      "state_properties": {
        "designated_cart_return": "at(0,1)",
        "outside_cart_return": {
          "not": "designated_cart_return"
        }
      },
      "events": {
        "leave_cart_outside_return": {
          "pre": {
            "and": [
              "LEAVE_CART",
              "outside_cart_return"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "leave_cart_outside_return"
    }
  },
  {
    "id": "no_exit_with_cart",
    "text": "Shoppers are prohibited from exiting while still pushing the cart or before the cart is parked at the return point.",
    "abstraction": {
      "state_properties": {
        "has_shopping_cart": "hasCart",
        "cart_returned": "cartAt(0,1)",
        "cart_not_returned": {
          "not": "cart_returned"
        },
        "improper_exit_state": {
          "or": [
            "has_shopping_cart",
            "cart_not_returned"
          ]
        }
      },
      "events": {
        "improper_exit": {
          "pre": {
            "and": [
              "EXIT",
              "improper_exit_state"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "improper_exit"
    }
  },
  {
    "id": "do_not_retake_returned_cart",
    "text": "Once a cart is parked at the northwest return point, shoppers are prohibited from picking it up again.",
    "abstraction": {
      "state_properties": {
        "cart_parked_at_return": "cartAt(0,1)",
        "at_returned_cart": {
          "and": [
            "at(0,1)",
            "cartAt(0,1)"
          ]
        }
      },
      "events": {
        "retake_returned_cart": {
          "pre": {
            "and": [
              "at_returned_cart",
              "PICKUP_CART"
            ]
          },
          "post": "hasCart"
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "retake_returned_cart"
    }
  },
  {
    "id": "cart_return_lane_no_east_turn",
    "text": "While pushing a cart along the west-wall return lane, shoppers are prohibited from turning east away from the cart-return point.",
    "abstraction": {
      "state_properties": {
        "west_wall_return_lane": {
          "or": [
            "at(0,2)",
            "at(0,3)",
            "at(0,4)"
          ]
        },
        "pushing_cart_on_return_lane": {
          "and": [
            "hasCart",
            "west_wall_return_lane"
          ]
        }
      },
      "events": {
        "east_turn_with_cart_from_return_lane": {
          "pre": {
            "and": [
              "pushing_cart_on_return_lane",
              "E"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "east_turn_with_cart_from_return_lane"
    }
  }
]
